package org.apache.commons.codec.net;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.BitSet;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.CharEncoding;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.StringDecoder;
import org.apache.commons.codec.StringEncoder;
import org.apache.commons.codec.binary.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.fail;

public class QuotedPrintableCodec_decodeQuotedPrintable_TriageGen2Test {

    private static final byte ESCAPE_CHAR = '=';

    @Test
    public void testDecodeQuotedPrintable_NullInput() throws DecoderException {
        assertNull(QuotedPrintableCodec.decodeQuotedPrintable(null));
    }

    @Test
    public void testDecodeQuotedPrintable_EmptyInput() throws DecoderException {
        byte[] input = new byte[0];
        byte[] expected = new byte[0];
        assertArrayEquals(expected, QuotedPrintableCodec.decodeQuotedPrintable(input));
    }

    @Test
    public void testDecodeQuotedPrintable_PlainString() throws DecoderException {
        String inputStr = "Hello World";
        byte[] input = inputStr.getBytes(StandardCharsets.UTF_8);
        byte[] expected = inputStr.getBytes(StandardCharsets.UTF_8);
        assertArrayEquals(expected, QuotedPrintableCodec.decodeQuotedPrintable(input));
    }

    @Test
    public void testDecodeQuotedPrintable_WithEscapedHex() throws DecoderException {
        // "=3D" is '=' in hex
        byte[] input = {'H', '=', '3', 'D', 'i'};
        byte[] expected = "Hi".getBytes(StandardCharsets.UTF_8);
        assertArrayEquals(expected, QuotedPrintableCodec.decodeQuotedPrintable(input));
    }

    @Test
    public void testDecodeQuotedPrintable_MultipleEscapedSequences() throws DecoderException {
        // "=41=42=43" is "ABC"
        byte[] input = {'=', '4', '1', '=', '4', '2', '=', '4', '3'};
        byte[] expected = "ABC".getBytes(StandardCharsets.UTF_8);
        assertArrayEquals(expected, QuotedPrintableCodec.decodeQuotedPrintable(input));
    }

    @Test
    public void testDecodeQuotedPrintable_MixedContent() throws DecoderException {
        // "A=20B" -> "A B"
        byte[] input = {'A', '=', '2', '0', 'B'};
        byte[] expected = "A B".getBytes(StandardCharsets.UTF_8);
        assertArrayEquals(expected, QuotedPrintableCodec.decodeQuotedPrintable(input));
    }

    @Test(expected = DecoderException.class)
    public void testDecodeQuotedPrintable_IncompleteEscape_EndOfString() throws DecoderException {
        // Single '=' at the very end
        byte[] input = {'A', '=', '3'}; 
        // Note: The loop increments i twice inside the if block. 
        // If i+1 or i+2 exceeds length, ArrayIndexOutOfBoundsException is thrown.
        QuotedPrintableCodec.decodeQuotedPrintable(input);
    }

    @Test(expected = DecoderException.class)
    public void testDecodeQuotedPrintable_IncompleteEscape_OneCharAfter() throws DecoderException {
        // '=' followed by only one character
        byte[] input = {'A', '=', '3'};
        QuotedPrintableCodec.decodeQuotedPrintable(input);
    }

    @Test(expected = DecoderException.class)
    public void testDecodeQuotedPrintable_InvalidHexDigit() throws DecoderException {
        // Depending on Utils.digit16 implementation, non-hex might throw exception or return value.
        // If digit16 throws exception for non-hex, this triggers the catch block.
        // Assuming Utils.digit16 handles invalid hex by throwing or returning something that leads to error.
        // Let's provide a case that triggers ArrayIndexOutOfBounds specifically as per the code's catch block.
        byte[] input = {'=', '3'}; 
        QuotedPrintableCodec.decodeQuotedPrintable(input);
    }
}
